WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is democracy?', 'A system of government in which power rests with the people, who exercise it directly or through elected representatives.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is direct democracy?', 'Citizens make decisions themselves, e.g. through referendums, rather than electing representatives.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is representative democracy?', 'Citizens elect representatives to make decisions on their behalf, and hold them accountable at elections.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'Give two advantages of direct democracy.', 'It gives decisions strong legitimacy and increases political participation and education.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'Give two disadvantages of direct democracy.', 'Complex issues are oversimplified, and it risks the tyranny of the majority and low turnout.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is pluralist democracy?', 'A democracy where power is dispersed among many competing groups, such as parties and pressure groups.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the franchise?', 'The right to vote in elections.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'When did women gain equal voting rights with men in the UK?', '1928 (Representation of the People (Equal Franchise) Act); some women over 30 had gained the vote in 1918.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'When was the voting age lowered to 18 in the UK?', '1969, by the Representation of the People Act.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are the arguments for lowering the voting age to 16?', '16-year-olds pay taxes, can work and marry; it may increase engagement; and 16-year-olds already vote in Scottish and Welsh elections.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are the arguments against votes at 16?', 'Lack of maturity and experience, low turnout among young voters, and inconsistency with other age limits.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a pressure group?', 'An organisation that seeks to influence government policy without seeking election to office.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is an insider group?', 'A pressure group with close links to and regular access to government, e.g. the BMA.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is an outsider group?', 'A pressure group without access to government, which uses public campaigns and direct action, e.g. Extinction Rebellion.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a think tank?', 'An organisation that researches and develops policy ideas to influence government, e.g. the Institute for Fiscal Studies.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is a lobbyist?', 'A professional paid to influence politicians and policy on behalf of clients.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is e-democracy?', 'The use of digital technology in democratic processes, e.g. online petitions and social media campaigns.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What happens to a UK Parliament e-petition with 100,000 signatures?', 'It is considered for debate in Parliament by the Petitions Committee.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What are rights in the UK?', 'Entitlements protected by law, such as freedom of speech, association and a fair trial, largely set out in the Human Rights Act 1998.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the role of the Equality Act 2010?', 'It consolidated anti-discrimination law, protecting nine characteristics including age, race, sex and disability.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'How have civil liberties been in conflict with security?', 'E.g. anti-terror laws allowing detention without charge and surveillance powers (Investigatory Powers Act 2016).', 21),
  ('Politics', 'Edexcel', 'alevel', '1.1', 'Democracy and Participation', 'What is the role of pressure groups in promoting rights?', 'Groups like Liberty and Amnesty campaign, bring legal cases, and raise awareness to protect rights.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a political party?', 'An organised group of people with shared ideas who seek to win elections and form a government.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the functions of political parties?', 'Representation, policy formulation, recruitment of leaders, political participation and forming government.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How are UK parties funded?', 'Membership fees, donations from individuals, businesses and trade unions, and state funding such as Short money.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is Cranborne money?', 'State funding for opposition parties in the House of Lords.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the arguments for state funding of parties?', 'It reduces the influence of wealthy donors, creates a level playing field, and allows parties to focus on policy.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the arguments against state funding of parties?', 'Taxpayers fund parties they oppose, it may favour established parties, and parties could lose touch with members.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the role of the Electoral Commission?', 'It regulates party finance and elections, including donations and spending limits.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What were the key features of Thatcherism?', 'Free markets, privatisation, reducing trade union power, low taxes, and a strong state on law and order.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What was New Labour?', 'The rebranding of Labour under Blair: the Third Way, accepting markets while investing in public services.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What are the key ideas of the Liberal Democrats?', 'Constitutional reform (including PR), civil liberties, pro-Europeanism, and environmental protection.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a minor party?', 'A party with limited representation in Parliament, e.g. the Greens or Reform UK.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a nationalist party?', 'A party seeking greater autonomy or independence for a nation, e.g. the SNP or Plaid Cymru.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a multi-party system?', 'A system where more than two parties have a realistic chance of forming or influencing government.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a dominant-party system?', 'A system where one party wins power repeatedly for a long period.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How did the 2010 election affect the party system?', 'It produced a hung parliament and a Conservative–Liberal Democrat coalition, the first since 1945.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What was the result of the 2024 general election?', 'Labour won a large majority (411 seats) on about 34% of the vote; the Conservatives fell to 121 seats; the Lib Dems won 72.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'How did Reform UK perform in 2024?', 'It won about 14% of the vote but only 5 seats, showing how FPTP penalises parties with evenly spread support.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is party leadership selection in the Conservative Party?', 'MPs narrow the candidates to two, then members vote in a ballot.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is party leadership selection in the Labour Party?', 'Candidates need nominations from MPs (and affiliates or CLPs), then members and registered supporters vote using a preferential system.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the impact of party leaders on electoral success?', 'Leaders shape party image and media coverage; popular leaders (e.g. Blair in 1997) help, unpopular ones hinder.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is a manifesto?', 'A document setting out a party''s policies and promises before an election.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.2', 'Political Parties', 'What is the Salisbury Convention?', 'The Lords do not block legislation promised in the governing party''s manifesto at second reading.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is First Past the Post?', 'A plurality system: the candidate with the most votes in each constituency wins, regardless of whether they have a majority.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the advantages of FPTP?', 'Simple, quick results, strong single-party governments, and a clear MP–constituency link.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the disadvantages of FPTP?', 'Disproportionate results, wasted votes, safe seats, and tactical voting.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a safe seat?', 'A constituency where one party has a large majority and is very likely to win.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a marginal seat?', 'A constituency where the winning party has a small majority, so it could change hands.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is tactical voting?', 'Voting for a less preferred candidate to prevent a disliked candidate from winning.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a wasted vote?', 'A vote that doesn''t contribute to electing a candidate, e.g. votes for losing candidates or surplus votes for winners.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is the Supplementary Vote?', 'Voters mark first and second preferences; if no candidate gets 50%, the top two remain and second preferences are counted. It was used for mayors and PCCs until 2023.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Why was the Supplementary Vote replaced in England?', 'The Elections Act 2022 switched mayoral and PCC elections to FPTP.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is STV?', 'The Single Transferable Vote: voters rank candidates in multi-member constituencies, and candidates reaching a quota are elected, with surplus and eliminated votes transferred.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Where is AMS used in the UK?', 'The Scottish Parliament, the Senedd (until 2026) and the London Assembly.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'How is the Senedd electoral system changing?', 'From 2026 it uses a closed list PR system with larger multi-member constituencies and 96 members.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the advantages of AMS?', 'More proportional than FPTP while keeping constituency MPs, and voters get two votes.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the disadvantages of AMS?', 'Two classes of representative, closed party lists give parties control, and it often produces coalitions.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is the D''Hondt formula?', 'A method of allocating list seats: votes ÷ (seats already won + 1), used in AMS regional lists.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a coalition government?', 'A government formed by two or more parties, usually when no party has a majority.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What is a referendum?', 'A vote by the electorate on a single issue.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Give two examples of UK-wide referendums.', 'The 1975 EEC membership referendum, the 2011 AV referendum and the 2016 EU referendum.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What was the result of the 2016 EU referendum?', 'Leave won 51.9% to 48.1% on a 72.2% turnout.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the arguments for referendums?', 'They give legitimacy to major constitutional decisions and increase participation.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'What are the arguments against referendums?', 'Complex issues are oversimplified, turnout can be low, and they undermine representative democracy.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.3', 'Electoral Systems', 'Are UK referendums legally binding?', 'No; due to parliamentary sovereignty they are advisory, although politically very hard to ignore.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is class voting?', 'Voting based on social class, traditionally working class for Labour and middle class for the Conservatives.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is partisan dealignment?', 'The decline in strong, long-term identification with a political party.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is class dealignment?', 'The weakening link between social class and voting behaviour.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does age affect voting behaviour?', 'Older voters are more likely to vote Conservative and to turn out; younger voters lean Labour, Green or Lib Dem.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does education affect voting?', 'Graduates were more likely to vote Remain and Labour or Lib Dem in recent elections; non-graduates more likely to vote Leave and Conservative (2019).', 5),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does ethnicity affect voting?', 'Ethnic minority voters have historically been more likely to vote Labour, although this varies between groups.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How does region affect voting?', 'Labour is strong in cities, Scotland (historically) and the North; the Conservatives in rural and southern England; the SNP has dominated Scotland since 2015.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is rational choice voting?', 'Voters make decisions based on their assessment of policies, performance and self-interest.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is issue voting?', 'Voting based on specific policy issues, such as Brexit or the economy.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the governing competence model?', 'Voters judge parties on their ability to govern effectively and manage the economy.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'How did Black Wednesday (1992) affect voting?', 'It damaged the Conservatives'' reputation for economic competence, contributing to their 1997 defeat.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2017 election?', 'Theresa May lost her majority, forming a confidence-and-supply agreement with the DUP; Labour gained among young voters.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the role of opinion polls?', 'They measure public opinion and may influence voting through bandwagon or underdog effects.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'Should opinion polls be banned before elections?', 'Arguments for: they can influence voters and were inaccurate (e.g. 2015). Against: freedom of speech and they inform tactical voting.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the role of the media in elections?', 'It informs voters, sets agendas, and can shape perceptions of leaders and parties.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is media bias?', 'Media coverage that favours one party or viewpoint, most notable in UK newspapers.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'Is UK broadcasting required to be impartial?', 'Yes; Ofcom requires broadcasters to maintain due impartiality, unlike newspapers.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the influence of social media on voting?', 'It allows targeted campaigning, spreads information quickly, and may create echo chambers and misinformation.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the ''Sun wot won it''?', 'The Sun''s claim that its support helped the Conservatives win in 1992, although evidence of media effects is contested.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2019 election''s ''Red Wall''?', 'The Conservatives won many traditionally Labour seats in the North and Midlands, reflecting Brexit and dealignment.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What was the significance of the 2024 election for voting behaviour?', 'Very high volatility, a record low combined Labour–Conservative vote share, and big gains for Reform UK, the Lib Dems and Greens.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.4', 'Voting Behaviour and the Media', 'What is the importance of campaigns in elections?', 'Campaigns can shift votes through leaders'' debates, events and gaffes, especially with more volatile voters.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is traditional conservatism?', 'A conservatism that values tradition, hierarchy, organic society and gradual change, based on Burke.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is paternalism?', 'The idea that those with power and wealth have a duty to look after those less fortunate (noblesse oblige).', 2),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the organic society?', 'Society is like a living organism, with interdependent parts, which develops naturally over time.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is pragmatism in conservatism?', 'Making decisions based on practical circumstances rather than abstract principles or ideology.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is conservatism''s view of human nature?', 'Humans are imperfect: morally, intellectually and psychologically, so need order and authority.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is One Nation conservatism?', 'Disraeli''s idea that society is united and the wealthy have a duty to help the poor, to prevent social division.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the New Right?', 'A combination of neoliberalism (free markets) and neoconservatism (social order and authority).', 7),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is neoliberalism?', 'An ideology supporting free markets, deregulation, privatisation and a minimal state in the economy.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is neoconservatism?', 'An ideology stressing traditional values, law and order, national identity and a strong state.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is libertarianism?', 'An ideology prioritising individual liberty and a minimal state.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Hobbes''s view of the state of nature?', 'Life without government would be "nasty, brutish and short", so people accept a strong sovereign for security.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Burke''s view of change?', 'Change should be gradual and organic, preserving the wisdom of tradition, as opposed to revolution.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Oakeshott''s view of politics?', 'Politics should be pragmatic and based on experience, not rationalist blueprints or ideology.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Rand''s objectivism?', 'A philosophy that rational self-interest is moral and laissez-faire capitalism is the ideal system.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is Nozick''s view of the state?', 'Only a minimal state protecting rights is justified; redistributive taxation violates self-ownership.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of property?', 'Property ownership gives security, encourages responsibility and respect for the law.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of the state?', 'The state should maintain order and authority; traditional conservatives accept intervention, the New Right wants a smaller state in the economy.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of the economy?', 'Traditional conservatives are pragmatic about intervention; neoliberals favour free markets.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is a tension between neoliberalism and neoconservatism?', 'Neoliberals want individual freedom and a small state; neoconservatives want a strong state enforcing social order and morality.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is authority in conservatism?', 'Authority comes from above and is natural and necessary to maintain order.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is hierarchy in conservatism?', 'Society is naturally hierarchical, with people in different positions performing different roles.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.5', 'Conservatism', 'What is the conservative view of human rationality?', 'Human reason is limited, so tradition and experience are better guides than abstract theory.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is individualism in liberalism?', 'The belief in the primacy of the individual over any social group or collective.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is classical liberalism?', 'Early liberalism emphasising individual freedom, a minimal state and free markets.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is modern liberalism?', 'Liberalism accepting that the state should intervene to enable individuals to achieve their potential (positive freedom).', 3),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the social contract?', 'The idea that the state''s authority rests on the consent of the governed.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Locke''s view of the state?', 'The state exists to protect natural rights to life, liberty and property, based on consent; people may rebel if it fails.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is limited government?', 'Government power restricted by a constitution, rights and the separation of powers.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is tolerance in liberalism?', 'Accepting views and lifestyles one disagrees with, as long as they don''t harm others.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of human nature?', 'Humans are rational and self-interested, but capable of reasoning and progress.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Mill''s view of liberty?', 'Individuals should be free to act as they wish, as long as they don''t harm others (the harm principle).', 9),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Wollstonecraft''s contribution to liberalism?', 'She argued women are rational beings entitled to the same rights and education as men.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Rawls''s theory of justice?', 'A just society is one people would choose behind a veil of ignorance, with equal liberties and inequalities only if they benefit the least well off.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is Friedan''s contribution to liberalism?', 'She argued women were trapped in domestic roles ("the problem that has no name") and campaigned for legal equality.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of the economy?', 'Classical liberals support free markets; modern liberals support a mixed economy with state intervention (Keynesianism).', 13),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of society?', 'Society is a collection of individuals; modern liberals accept that social conditions affect individuals'' freedom.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is meritocracy?', 'A society where success is based on ability and effort rather than birth or privilege.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is liberal democracy?', 'A democracy with free elections, the rule of law, protection of rights and limited government.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the rule of law?', 'Everyone, including government, is subject to the law.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is equality of opportunity?', 'Everyone should have the same chance to succeed, regardless of background.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is foundational equality?', 'All humans are born with equal worth and rights.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is formal equality?', 'All individuals have the same legal and political rights.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'What is the liberal view of the state?', 'The state is a necessary evil (classical) or an enabler of freedom (modern).', 21),
  ('Politics', 'Edexcel', 'alevel', '1.6', 'Liberalism', 'Why do liberals fear the tyranny of the majority?', 'Majorities may oppress minorities and limit individual freedom, so rights must be protected.', 22),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is collectivism?', 'The belief that collective action is more effective than individual action in achieving social and economic goals.', 1),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is common ownership?', 'Productive resources should be owned collectively, by the state or workers, rather than privately.', 2),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is social justice?', 'A fair distribution of wealth, opportunities and privileges in society.', 3),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is equality of outcome?', 'An equal distribution of wealth and resources, which socialists see as necessary for true equality.', 4),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of human nature?', 'Humans are social, cooperative and shaped by their environment.', 5),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is revolutionary socialism?', 'The belief that capitalism must be overthrown by revolution, e.g. Marxism.', 6),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is evolutionary socialism?', 'The belief that socialism can be achieved gradually through democratic means and reform.', 7),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is social democracy?', 'A form of socialism accepting a mixed economy and capitalism with welfare state intervention to reduce inequality.', 8),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the Third Way?', 'A revisionist approach combining market economics with social justice, associated with Giddens and New Labour.', 9),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Marx''s view of class?', 'Society is divided into the bourgeoisie (owners) and proletariat (workers), whose conflict drives history.', 10),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Webb''s contribution to socialism?', 'Beatrice Webb was a Fabian who argued socialism could be achieved gradually through reform and expertise.', 11),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Luxemburg''s view of socialism?', 'Capitalism must be overthrown by a mass revolutionary movement, but socialism must be democratic.', 12),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Crosland''s view of socialism?', 'Socialism is about equality and social justice, achievable within a mixed economy with welfare and education.', 13),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is Giddens''s view of socialism?', 'The Third Way: accept globalisation and markets while investing in human capital and social inclusion.', 14),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of the state?', 'Revolutionary socialists see the state as a tool of class oppression; social democrats see it as a means to achieve reform.', 15),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of the economy?', 'The economy should be run for social needs rather than profit, through common ownership or regulation.', 16),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist view of society?', 'Society is shaped by class and economic structures; inequality is caused by capitalism.', 17),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is workers'' control?', 'The idea that workers should manage their workplaces democratically.', 18),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is cooperation in socialism?', 'Humans naturally work together for mutual benefit rather than competing.', 19),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is fraternity?', 'The bonds of comradeship and solidarity between people.', 20),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is the socialist critique of capitalism?', 'It is exploitative, creates inequality, alienation, and instability.', 21),
  ('Politics', 'Edexcel', 'alevel', '1.7', 'Socialism', 'What is alienation?', 'Marx''s idea that under capitalism workers are separated from the products of their labour, the process, each other and their humanity.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a constitution?', 'A set of rules that establishes the structure and powers of government and the relationship between the state and citizens.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an uncodified constitution?', 'A constitution not contained in a single document, drawn from several sources.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an unentrenched constitution?', 'A constitution that can be changed by ordinary legislation, without special procedures.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a unitary constitution?', 'Sovereignty lies with a central authority, which may delegate but not share power.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the sources of the UK constitution?', 'Statute law, common law, conventions, authoritative works and treaties.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is statute law?', 'Laws passed by Parliament, e.g. the Human Rights Act 1998.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is common law?', 'Law based on judicial decisions and precedent.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is a convention?', 'An unwritten rule that is followed by custom, e.g. the monarch gives royal assent to bills.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is an authoritative work?', 'A written text explaining how the constitution works, e.g. Bagehot''s The English Constitution or Erskine May.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the principle of parliamentary sovereignty?', 'Parliament can make or unmake any law, and no Parliament can bind its successors.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the rule of law in the UK constitution?', 'All are equal before the law, no one is above the law, and punishment only follows a breach of law.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Magna Carta (1215)?', 'A charter limiting royal power and establishing that the monarch is subject to the law.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Bill of Rights 1689?', 'It established parliamentary sovereignty over the monarch and rights such as free elections.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was devolution in 1998?', 'The transfer of powers from Westminster to a Scottish Parliament, a Welsh Assembly and a Northern Ireland Assembly.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Human Rights Act 1998?', 'It incorporated the European Convention on Human Rights into UK law.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the House of Lords Act 1999?', 'It removed all but 92 hereditary peers from the House of Lords.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was the Fixed-term Parliaments Act 2011?', 'It set five-year fixed terms and restricted early elections; it was repealed by the Dissolution and Calling of Parliament Act 2022.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the West Lothian Question?', 'Why Scottish MPs can vote on English-only matters while English MPs can''t vote on devolved Scottish matters.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What was English Votes for English Laws (EVEL)?', 'A 2015 procedure giving English MPs a veto on England-only laws; it was abolished in 2021.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the arguments for a codified constitution?', 'Clarity, protection of rights, limits on government power, and education of citizens.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What are the arguments against a codified constitution?', 'Loss of flexibility, judges gaining political power, and difficulty agreeing on its content.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.1', 'The Constitution', 'What is the Sewel Convention?', 'Westminster will not normally legislate on devolved matters without the consent of the devolved legislature.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the House of Commons?', 'The elected lower chamber of Parliament, with 650 MPs.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the House of Lords?', 'The unelected upper chamber, made up of life peers, hereditary peers and bishops.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the functions of Parliament?', 'Legislation, scrutiny of the executive, representation, and debate.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the legislative process in the UK?', 'First reading, second reading, committee stage, report stage, third reading, then the other House, and royal assent.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a Public Bill Committee?', 'A committee that examines bills line by line after second reading.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a select committee?', 'A committee that scrutinises government departments or policy areas.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is Prime Minister''s Questions?', 'A weekly session where MPs question the Prime Minister.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of the opposition?', 'To scrutinise and criticise the government and present itself as an alternative government.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is an Opposition Day?', 'Days (20 per session) when opposition parties choose the topics for debate.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the Backbench Business Committee?', 'Created in 2010, it schedules debates chosen by backbench MPs.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a Private Member''s Bill?', 'A bill introduced by a backbench MP or peer rather than the government.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a ten-minute rule bill?', 'A Private Member''s Bill introduced with a short speech, often used to raise awareness.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of the whips?', 'They maintain party discipline and ensure MPs vote with the party.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a backbench rebellion?', 'When MPs vote against their party''s position.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the role of MPs?', 'Representing constituents, scrutinising government, legislating and supporting their party.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the trustee model of representation?', 'MPs use their own judgement on behalf of constituents (Burke).', 16),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the delegate model of representation?', 'MPs act according to the wishes of their constituents.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is the mandate model of representation?', 'MPs are elected to deliver the manifesto of their party.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the powers of the House of Lords?', 'It can delay most legislation for about a year, revise bills, scrutinise government and hold debates.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the arguments for an elected House of Lords?', 'Democratic legitimacy, accountability, and ending patronage.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What are the arguments against an elected House of Lords?', 'It could challenge the Commons, lose expertise, and create gridlock.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.2', 'Parliament', 'What is a life peer?', 'A member of the House of Lords appointed for life, whose title is not inherited.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the Cabinet?', 'The committee of senior ministers, chaired by the Prime Minister, that makes key decisions.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the Prime Minister?', 'The head of government, usually the leader of the largest party in the House of Commons.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are the powers of the Prime Minister?', 'Appointing ministers, setting the agenda, controlling Cabinet, leading the party, and using the royal prerogative.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are the constraints on the Prime Minister?', 'Size of majority, party unity, public opinion, events, Cabinet, and the media.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the core executive?', 'The network of institutions and people at the centre of government, including the PM, Cabinet, senior civil servants and advisers.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is a secondary legislation?', 'Rules made by ministers under powers granted by an Act of Parliament (statutory instruments).', 6),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the civil service?', 'Permanent, politically neutral officials who implement government policy.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is collective ministerial responsibility?', 'Ministers must publicly support all government decisions or resign.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is individual ministerial responsibility?', 'Ministers are responsible for their own conduct and the actions of their department.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Give an example of a resignation due to collective responsibility.', 'Robin Cook resigned in 2003 over the Iraq War.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Give an example of a resignation over personal conduct.', 'Matt Hancock resigned in 2021 after breaching COVID guidance.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is a Cabinet reshuffle?', 'When the Prime Minister changes the roles of ministers.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What are special advisers?', 'Political appointees who advise ministers and are not politically neutral, e.g. Dominic Cummings.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is prime ministerial government?', 'The view that the PM dominates the executive, rather than Cabinet.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is Cabinet government?', 'The view that decisions are made collectively by the Cabinet.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is presidentialism?', 'The idea that the UK PM has become more like a president, with personal mandates and dominance.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Thatcher fall in 1990?', 'Loss of Cabinet support, the poll tax, and divisions over Europe led to a leadership challenge.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Theresa May resign in 2019?', 'She failed to pass her Brexit withdrawal agreement and lost the support of her party.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why did Boris Johnson resign in 2022?', 'Scandals such as Partygate and the Pincher affair led to mass ministerial resignations.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'Why was Liz Truss''s premiership so short?', 'Her 2022 mini-budget caused market turmoil, destroying her authority; she resigned after 49 days.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the role of the Cabinet Office?', 'It supports the PM and Cabinet and coordinates government policy.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.3', 'Prime Minister and Executive', 'What is the royal prerogative?', 'Powers historically held by the monarch, now mostly exercised by ministers, e.g. treaty-making and deploying the armed forces.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the Supreme Court?', 'The highest court of appeal in the UK, established in 2009 to replace the Law Lords.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial review?', 'The process by which courts review the lawfulness of decisions by public bodies.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial independence?', 'Judges are free from political influence, e.g. security of tenure, salary protection and independent appointment.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is judicial neutrality?', 'Judges make decisions impartially, without personal bias.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'How are UK Supreme Court judges appointed?', 'By an independent selection commission, with the Lord Chancellor''s approval.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is a declaration of incompatibility?', 'A court ruling that a law is incompatible with the Human Rights Act; Parliament decides whether to change it.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is ultra vires?', 'Acting beyond legal authority.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'Give an example of a significant Supreme Court case on rights.', 'Belmarsh (2004, then Law Lords): detention of foreign terror suspects without trial was incompatible with human rights.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the Rwanda case (2023)?', 'The Supreme Court ruled that the Rwanda asylum plan was unlawful because of the risk of refoulement.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the relationship between Parliament and the executive?', 'The executive usually dominates Parliament through its majority, but Parliament scrutinises and can defeat government.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the relationship between the UK and the EU after Brexit?', 'The UK left in 2020, ending the supremacy of EU law and restoring parliamentary sovereignty over those areas.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the Factortame case (1990)?', 'The Law Lords disapplied an Act of Parliament that conflicted with EU law, showing EU law''s supremacy at the time.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is legal sovereignty?', 'The legal authority to make law, held by Parliament in the UK.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is political sovereignty?', 'Where political power actually lies, arguably with the electorate or the government.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is pooled sovereignty?', 'Sharing sovereignty with other states in international organisations, such as the EU.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the significance of the Miller (2017) case?', 'The government needed parliamentary approval to trigger Article 50.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What was the significance of Miller/Cherry (2019)?', 'The Supreme Court ruled Johnson''s prorogation of Parliament unlawful.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is a hung parliament?', 'When no single party has a majority of seats in the House of Commons.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the relationship between the executive and judiciary?', 'Judges can review executive actions through judicial review and uphold rights.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is parliamentary privilege?', 'Legal immunity for MPs and peers for what they say in parliamentary proceedings.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the role of the European Court of Human Rights?', 'It hears cases on the European Convention on Human Rights; the UK remains a member despite leaving the EU.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.4', 'Relations Between the Branches', 'What is the separation of powers?', 'The division of government into legislative, executive and judicial branches, each checking the others.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the core idea of anarchism?', 'The rejection of the state and all forms of coercive authority.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is collectivist anarchism?', 'Anarchism based on common ownership and cooperation, e.g. anarcho-communism and anarcho-syndicalism.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is individualist anarchism?', 'Anarchism prioritising individual sovereignty and rejecting the state, e.g. anarcho-capitalism and egoism.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is anarcho-communism?', 'A stateless society with common ownership and distribution according to need.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is anarcho-syndicalism?', 'Anarchism using trade unions and general strikes to overthrow capitalism and the state.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is anarcho-capitalism?', 'The belief that the free market can replace the state entirely, including provision of security and justice.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is egoism?', 'Stirner''s belief that individuals should act solely in their own interest, rejecting all external authority.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is Stirner''s contribution to anarchism?', 'He argued the individual ego is supreme, and rejected the state, morality and religion.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is Goldman''s contribution to anarchism?', 'She linked anarchism with feminism and opposed the state, religion and marriage as oppressive.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of human nature?', 'Humans are naturally sociable and cooperative (collectivists) or rational and self-interested (individualists).', 10),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of the economy?', 'Collectivists want common ownership; individualists want free markets without the state.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of the state?', 'The state is coercive, corrupting and unnecessary.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of society?', 'Society can organise itself naturally without the state.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is direct action?', 'Political action outside formal institutions, such as protests, strikes and sabotage.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is mutualism?', 'Proudhon''s idea of a society based on voluntary exchange and cooperative banks.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist critique of religion?', 'Religion is a form of authority that suppresses individual freedom.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist critique of capitalism?', 'Collectivists argue capitalism exploits workers and relies on the state to protect property.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of liberty?', 'True freedom is only possible without the state.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is propaganda by the deed?', 'The use of violent acts to inspire revolution, used by some anarchists in the late 19th century.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of democracy?', 'Representative democracy is a form of domination; anarchists favour direct democracy or none.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What are the criticisms of anarchism?', 'It is utopian, unrealistic about human nature, and could lead to chaos.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.5', 'Anarchism', 'What is the anarchist view of economic freedom?', 'Collectivists see economic freedom as freedom from exploitation; individualists as freedom of exchange.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is ecologism?', 'An ideology that places the natural environment at the centre of political thinking.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is shallow ecology?', 'An anthropocentric approach that protects the environment for human benefit, e.g. sustainable development.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is deep ecology?', 'An ecocentric approach that nature has intrinsic value independent of humans.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is sustainability?', 'Meeting the needs of the present without compromising future generations.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is environmental ethics?', 'The idea that moral consideration should extend to future generations, animals and nature.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is ecological consciousness?', 'A deep awareness of humanity''s connection to nature.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is Lovelock''s Gaia hypothesis?', 'The Earth is a self-regulating living system.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is Carson''s contribution to ecologism?', 'Silent Spring (1962) exposed the damage caused by pesticides, starting the modern environmental movement.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is Schumacher''s idea of ''small is beautiful''?', 'Economies should be small-scale, local and sustainable, using appropriate technology.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is social ecology?', 'Bookchin''s idea that environmental problems are caused by social hierarchies and capitalism.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is eco-socialism?', 'The view that capitalism causes environmental destruction, so common ownership is needed.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is eco-anarchism?', 'The belief that small, decentralised communities living in harmony with nature are ideal.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is eco-feminism?', 'The view that patriarchy and environmental destruction are linked.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is the ecologist view of the economy?', 'Opposition to endless growth; support for a steady-state or zero-growth economy.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is the ecologist view of the state?', 'Shallow greens accept the state; deep greens favour decentralised communities.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is anthropocentrism?', 'A human-centred view that nature exists for human use.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is ecocentrism?', 'A nature-centred view that all life has intrinsic value.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is the ecologist view of human nature?', 'Humans are part of nature, not separate from or above it.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is the precautionary principle?', 'Taking action to prevent harm even if there is not full scientific certainty.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is Leopold''s land ethic?', 'Humans should treat land as a community to which they belong, not a commodity.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What are the criticisms of ecologism?', 'It may be anti-growth and anti-development, and deep ecology is seen as impractical.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.6', 'Ecologism', 'What is green consumerism?', 'Buying environmentally friendly products, criticised by deep ecologists for not tackling underlying problems.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is liberal feminism?', 'Feminism seeking legal and political equality for women within the existing system through reform.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is radical feminism?', 'Feminism arguing that patriarchy pervades all aspects of society and must be overthrown.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is socialist feminism?', 'Feminism arguing that patriarchy is linked to capitalism, which exploits women''s unpaid domestic labour.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is postmodern feminism?', 'Feminism rejecting the idea of a single female experience and challenging fixed categories of gender.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is intersectionality?', 'The idea that different forms of oppression (race, class, gender) interact.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the first wave of feminism?', 'The 19th and early 20th century movement for legal and political rights, especially suffrage.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the second wave of feminism?', 'The 1960s–80s movement challenging social and cultural inequalities, e.g. in the family and workplace.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the third wave of feminism?', 'Feminism from the 1990s emphasising diversity and individual identity.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is equality feminism?', 'The belief that women and men are fundamentally equal and should be treated the same.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is difference feminism?', 'The belief that women and men are different, and women''s differences should be celebrated.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is Millett''s contribution to feminism?', 'Sexual Politics (1970) argued patriarchy operates through all social institutions, especially the family.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is Rowbotham''s contribution to feminism?', 'A socialist feminist who argued women''s oppression is linked to capitalism and class.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the feminist view of human nature?', 'Equality feminists argue gender is socially constructed; difference feminists see natural differences.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the feminist view of the state?', 'Liberal feminists see the state as a tool for reform; radical feminists see it as patriarchal.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the feminist view of the economy?', 'Socialist feminists highlight unpaid domestic labour and economic exploitation of women.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the feminist view of society?', 'Society is patriarchal, with women systematically disadvantaged.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the public/private divide?', 'The separation of politics (public, male) from the family (private, female), which feminists challenge.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is gender?', 'The socially constructed roles and behaviours associated with being male or female.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is sex?', 'The biological differences between males and females.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the glass ceiling?', 'An invisible barrier preventing women from reaching senior positions.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What is the gender pay gap?', 'The difference in average earnings between men and women.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.7', 'Feminism', 'What are the criticisms of feminism?', 'It is divided, may not represent all women, and some argue equality has largely been achieved.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is multiculturalism?', 'The idea that different cultures can coexist within a society, and that cultural diversity should be recognised and valued.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is liberal multiculturalism?', 'Multiculturalism within a framework of liberal values, tolerance and individual rights.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is pluralist multiculturalism?', 'Multiculturalism that accepts deep value diversity, without giving liberal values priority.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is cosmopolitan multiculturalism?', 'Multiculturalism that celebrates cultural mixing and a global identity.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is conservative multiculturalism?', 'A critique suggesting diversity may undermine national identity and social cohesion.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is identity politics?', 'Politics based on the interests and perspectives of social groups defined by identity.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is minority rights?', 'Rights granted to minority groups to protect their culture and identity.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is the politics of recognition?', 'Taylor''s idea that groups need their identity recognised and respected.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is Parekh''s contribution to multiculturalism?', 'He argued cultural diversity is valuable, and societies should be a "community of communities".', 9),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is Kymlicka''s view of multiculturalism?', 'Minority rights are compatible with liberalism, as culture provides a context for individual choice.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is Berlin''s view of pluralism?', 'There are many legitimate but conflicting values, and no single way of life is best.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is Modood''s view of multiculturalism?', 'Religion is an important identity that should be recognised, not privatised.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is assimilation?', 'Minorities adopting the culture of the majority.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is integration?', 'Minorities participating fully in society while keeping aspects of their culture.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is social cohesion?', 'The bonds that bring people together in a society.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is the criticism that multiculturalism causes segregation?', 'Critics argue it encourages separate communities living parallel lives.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is the liberal criticism of multiculturalism?', 'It may tolerate illiberal practices that harm individuals, especially women.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is the conservative criticism of multiculturalism?', 'It may weaken national identity and cohesion.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is the feminist criticism of multiculturalism?', 'Minority cultural practices may oppress women.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is interculturalism?', 'An approach emphasising dialogue and interaction between cultures.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is cultural diversity?', 'The existence of a variety of cultural groups within a society.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.8', 'Multiculturalism', 'What is multicultural citizenship?', 'Kymlicka''s idea of granting group-differentiated rights to minorities.', 22),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is nationalism?', 'The belief that the nation is the central principle of political organisation.', 1),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is liberal nationalism?', 'Nationalism based on self-determination, democracy and respect for other nations.', 2),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is conservative nationalism?', 'Nationalism emphasising tradition, national identity and social cohesion.', 3),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is anti-colonial nationalism?', 'Nationalism seeking independence from colonial rule.', 4),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is expansionist nationalism?', 'Aggressive nationalism seeking to expand a nation''s territory, often based on superiority.', 5),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is self-determination?', 'The right of a nation to govern itself.', 6),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is the nation-state?', 'A state whose borders match those of a nation.', 7),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is cultural nationalism?', 'Nationalism focusing on culture, language and traditions rather than political independence.', 8),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is ethnic nationalism?', 'Nationalism based on a shared ethnicity or ancestry.', 9),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is civic nationalism?', 'Nationalism based on shared values and citizenship rather than ethnicity.', 10),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is Garvey''s contribution to nationalism?', 'He promoted Black nationalism and pan-Africanism, encouraging pride and self-reliance.', 11),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is Mazzini''s contribution to nationalism?', 'He promoted Italian unification and liberal nationalism based on self-determination.', 12),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is Maurras''s contribution to nationalism?', 'He promoted integral nationalism, an authoritarian and exclusive form of French nationalism.', 13),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is chauvinism?', 'The belief in the superiority of one''s own nation.', 14),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is racialism?', 'The belief that races are distinct and should be separated, used in expansionist nationalism.', 15),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is the nationalist view of human nature?', 'Humans naturally form communities and have a need to belong to a nation.', 16),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is the nationalist view of the state?', 'Each nation should have its own state.', 17),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is the nationalist view of society?', 'Society is based on a shared national identity.', 18),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is the nationalist view of the economy?', 'Varies: some favour protectionism and economic self-sufficiency.', 19),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is internationalism?', 'Cooperation between nations; liberal nationalists support it, while expansionists reject it.', 20),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What is pan-nationalism?', 'A movement to unite all members of a nation or ethnic group, e.g. pan-Africanism.', 21),
  ('Politics', 'Edexcel', 'alevel', '2.9', 'Nationalism', 'What are the criticisms of nationalism?', 'It can lead to conflict, exclusion of minorities and aggression.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is a codified constitution?', 'A constitution written in a single document, like the US Constitution.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is an entrenched constitution?', 'A constitution protected by special amendment procedures, making it hard to change.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What are the Articles of the US Constitution?', 'Article I: Congress; Article II: the President; Article III: the judiciary; others cover states, amendment and supremacy.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Bill of Rights?', 'The first ten amendments to the US Constitution, protecting individual rights.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the First Amendment?', 'Freedom of religion, speech, press, assembly and petition.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Second Amendment?', 'The right to keep and bear arms.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Fourteenth Amendment?', 'It guarantees equal protection of the laws and due process to all citizens.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'How is the US Constitution amended?', 'Proposed by two-thirds of both houses of Congress (or a convention called by two-thirds of states), and ratified by three-quarters of the states.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'How many amendments have there been?', '27, the last being ratified in 1992.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the separation of powers in the US?', 'Legislative power with Congress, executive power with the President, and judicial power with the courts.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is federalism?', 'Power is shared between the federal government and the states.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is dual federalism?', 'Federal and state governments operate in separate spheres (the "layer cake" model).', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is cooperative federalism?', 'Federal and state governments work together, e.g. through grants (the "marble cake" model).', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is new federalism?', 'Returning power to the states, associated with Nixon and Reagan.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Commerce Clause?', 'It gives Congress power to regulate interstate commerce, used to expand federal power.', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Necessary and Proper Clause?', 'It gives Congress power to make laws needed to carry out its enumerated powers.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the Supremacy Clause?', 'Federal law takes precedence over state law.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What are the strengths of the US Constitution?', 'Protects rights, limits government, is flexible through interpretation, and has lasted over 230 years.', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What are the weaknesses of the US Constitution?', 'Hard to amend, outdated provisions (e.g. the Second Amendment debate), and the Electoral College.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the role of the states?', 'States control many areas, e.g. education, criminal law and elections.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'What is the significance of the Tenth Amendment?', 'Powers not given to the federal government are reserved to the states or the people.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.1', 'US Constitution and Federalism', 'How has federal power grown?', 'Through the New Deal, the Great Society, the Commerce Clause, and responses to crises such as 9/11.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the House of Representatives?', 'The lower chamber of Congress, with 435 members elected every two years based on population.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the Senate?', 'The upper chamber, with 100 members (two per state) elected for six years.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What are the powers of Congress?', 'Legislation, taxation, declaring war, confirming appointments (Senate), ratifying treaties (Senate) and impeachment.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the power of the purse?', 'Congress controls taxation and spending.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the legislative process in the US?', 'Introduction, committee stage, floor debate and vote in both houses, a conference committee if needed, and presidential approval or veto.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is a presidential veto?', 'The President''s rejection of a bill, which can be overridden by two-thirds of both houses.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is a pocket veto?', 'When the President doesn''t sign a bill within 10 days and Congress has adjourned, so it fails.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the role of the Speaker of the House?', 'The presiding officer and leader of the majority party, controlling the legislative agenda.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the role of the Senate Majority Leader?', 'The leader of the majority party in the Senate, controlling the floor agenda.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is a standing committee?', 'A permanent committee that scrutinises legislation and oversees policy areas.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the House Rules Committee?', 'It sets the terms of debate for bills in the House.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the role of Congress in oversight?', 'Investigating and scrutinising the executive through hearings and investigations.', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the confirmation power of the Senate?', 'The Senate must approve presidential appointments, including Supreme Court justices and Cabinet members.', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the treaty ratification power?', 'Treaties require approval by two-thirds of the Senate.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is impeachment?', 'The House can impeach (charge) federal officials; the Senate tries them, and removal requires a two-thirds vote.', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'How many times has a President been impeached?', 'Three presidents, four impeachments: Andrew Johnson (1868), Clinton (1998) and Trump (2019 and 2021). None was removed by the Senate.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is partisanship in Congress?', 'Members voting along party lines; it has increased greatly in recent decades.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is gridlock?', 'When Congress and the President fail to pass legislation because of divided government or partisanship.', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is divided government?', 'When one party controls the presidency and the other controls one or both houses of Congress.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is representation in Congress?', 'Members represent their constituents, parties and interest groups.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is pork-barrel politics?', 'Spending targeted at a member''s district to gain support.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.2', 'US Congress', 'What is the significance of incumbency?', 'Incumbents have very high re-election rates due to name recognition, funding and constituency service.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What are the formal powers of the President?', 'Commander-in-chief, proposing legislation, veto, appointments, treaties, pardons and executing laws.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What are the informal powers of the President?', 'Persuasion, the electoral mandate, the bully pulpit, and executive orders.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the power to persuade?', 'Neustadt''s argument that the President''s real power lies in persuading others.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is an executive order?', 'A directive issued by the President to manage the federal government, without congressional approval.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is a signing statement?', 'A statement issued by the President when signing a bill, which may interpret or challenge parts of it.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the Executive Office of the President?', 'The agencies that support the President, including the White House Office and the Office of Management and Budget.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the Cabinet in the US?', 'The heads of the executive departments, who advise the President but have no collective responsibility.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the bully pulpit?', 'The President''s platform to speak directly to the public and influence opinion.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the imperial presidency?', 'Schlesinger''s idea that the President has become too powerful, especially in foreign policy.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the imperilled presidency?', 'The idea that the President is too weak because of constraints from Congress, courts and media.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What are the constraints on the President?', 'Congress, the Supreme Court, the Constitution, federalism, public opinion and the media.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the War Powers Resolution 1973?', 'It requires the President to notify Congress within 48 hours of deploying troops and limits deployments to 60 days without approval.', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the role of the Vice President?', 'President of the Senate with a tie-breaking vote, and first in line to succeed the President.', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the 25th Amendment?', 'It sets out procedures for presidential succession and disability.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is a lame duck President?', 'A President in the final period of office, often with reduced power.', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the honeymoon period?', 'The early period of a presidency when the President has high approval and can achieve more.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the role of the President in foreign policy?', 'Commander-in-chief, negotiating treaties, appointing ambassadors, and leading diplomacy.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is executive privilege?', 'The President''s claim to withhold information from Congress and the courts, limited by US v Nixon (1974).', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the significance of US v Nixon (1974)?', 'The Supreme Court ruled the President must hand over the Watergate tapes, limiting executive privilege.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is the unitary executive theory?', 'The view that the President has complete control over the executive branch.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is a presidential mandate?', 'The authority to carry out policies based on winning an election.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.3', 'US Presidency', 'What is presidential approval rating?', 'A measure of public support for the President, which affects their power.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is judicial review in the US?', 'The power of courts to declare laws and executive actions unconstitutional.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is the Supreme Court''s composition?', 'Nine justices appointed for life by the President and confirmed by the Senate.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is judicial activism?', 'When judges actively interpret the Constitution to shape policy.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is judicial restraint?', 'When judges defer to elected branches and follow precedent.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is originalism?', 'Interpreting the Constitution according to its original meaning.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is the living constitution?', 'Interpreting the Constitution in light of current values.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is stare decisis?', 'Following precedent in judicial decisions.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Brown v Board of Education (1954)?', 'It ruled racial segregation in public schools unconstitutional.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Roe v Wade (1973)?', 'It established a constitutional right to abortion.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Dobbs v Jackson (2022)?', 'It overturned Roe v Wade, returning abortion regulation to the states.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Obergefell v Hodges (2015)?', 'It legalised same-sex marriage nationwide.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was DC v Heller (2008)?', 'It ruled the Second Amendment protects an individual right to own firearms.', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Students for Fair Admissions v Harvard (2023)?', 'It ruled race-conscious affirmative action in college admissions unconstitutional.', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is a swing justice?', 'A justice whose vote often decides close cases, e.g. Anthony Kennedy.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is the politicisation of the Supreme Court?', 'The perception that justices vote along ideological lines and that appointments are highly partisan.', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was the controversy over the Garland nomination (2016)?', 'The Republican Senate refused to hold hearings for Obama''s nominee, Merrick Garland.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is the current ideological balance of the Supreme Court?', 'A 6–3 conservative majority following Trump''s three appointments.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is the civil rights movement?', 'The struggle for equal rights for African Americans, especially in the 1950s and 60s.', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was the Civil Rights Act 1964?', 'It banned discrimination based on race, colour, religion, sex or national origin.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was the Voting Rights Act 1965?', 'It outlawed discriminatory voting practices such as literacy tests.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What was Shelby County v Holder (2013)?', 'It struck down a key part of the Voting Rights Act requiring federal pre-clearance for some states.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.4', 'US Supreme Court and Civil Rights', 'What is affirmative action?', 'Policies giving preferential treatment to disadvantaged groups to address past discrimination.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the presidential election process?', 'Invisible primary, primaries and caucuses, national conventions, the general election campaign, and the Electoral College vote.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the Electoral College?', '538 electors allocated to states based on congressional representation; a candidate needs 270 to win.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is winner-takes-all?', 'In most states, the candidate with the most votes wins all the state''s electoral votes.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'Which states don''t use winner-takes-all?', 'Maine and Nebraska allocate some electoral votes by congressional district.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is a swing state?', 'A state where either party could win, e.g. Pennsylvania, Michigan and Wisconsin.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is a national convention?', 'A party meeting that formally nominates its presidential candidate and adopts a platform.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the significance of Super Tuesday?', 'The day when many states hold primaries, often decisive in the nomination race.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is campaign finance?', 'The funding of election campaigns, regulated by law.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is a Super PAC?', 'A political action committee that can raise and spend unlimited amounts, but can''t coordinate directly with campaigns.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is soft money?', 'Money donated to parties for general activities rather than specific candidates, restricted by the Bipartisan Campaign Reform Act 2002.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the role of interest groups in the US?', 'They lobby Congress and the executive, fund campaigns and bring legal cases.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the NRA?', 'The National Rifle Association, an influential interest group defending gun rights.', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is lobbying?', 'Attempting to influence legislators and officials on behalf of interest groups.', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the revolving door?', 'Movement of people between government and lobbying roles.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What are the two main parties in the US?', 'The Democrats (liberal) and the Republicans (conservative).', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is party polarisation?', 'Parties moving further apart ideologically, with fewer moderates.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the role of third parties?', 'They can influence debate and act as spoilers, e.g. Ralph Nader in 2000.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is voter turnout in US elections?', 'Relatively low compared with other democracies, especially in midterms.', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the midterm election?', 'Elections held halfway through a presidential term, for all House seats and a third of the Senate.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What factors influence voting in the US?', 'Race, religion, gender, education, age, region and the economy.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is voter ID laws'' impact?', 'Critics argue they suppress minority turnout; supporters say they prevent fraud.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.5', 'US Democracy and Participation', 'What is the significance of the 2020 election?', 'Biden won, and Trump''s refusal to accept the result led to the 6 January 2021 Capitol attack.', 22),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the rational approach to comparative politics?', 'It explains outcomes by the self-interested choices of individuals.', 1),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the cultural approach to comparative politics?', 'It explains outcomes by shared values, beliefs and norms.', 2),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the structural approach?', 'It explains outcomes by institutions and the rules that shape behaviour.', 3),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US constitutions differ?', 'The UK''s is uncodified, unentrenched and unitary; the US''s is codified, entrenched and federal.', 4),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US legislatures differ?', 'Congress has more power over legislation and appointments; the UK Parliament is dominated by the executive.', 5),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US executives differ?', 'The US President is elected separately with fixed terms; the UK PM depends on parliamentary support.', 6),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US Supreme Courts differ?', 'The US Court can strike down laws; the UK Court can''t overturn Acts of Parliament.', 7),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How are rights protected in the UK and US?', 'The US has an entrenched Bill of Rights; the UK relies on the Human Rights Act, which Parliament can amend.', 8),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do UK and US parties differ?', 'UK parties are more centralised and disciplined; US parties are decentralised and candidate-centred.', 9),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do UK and US pressure groups differ?', 'US groups have more access points and influence, including through the courts and campaign finance.', 10),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How does federalism compare with devolution?', 'Federalism is constitutionally entrenched; devolution can in theory be revoked by Westminster.', 11),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How does the separation of powers compare?', 'The US has a strict separation; the UK has a fusion of executive and legislature.', 12),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'Why do US legislators rebel more often than UK MPs?', 'Weaker party discipline, separate elections, and primaries make members more responsive to constituents.', 13),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US differ in their elections?', 'The US has fixed terms, primaries and the Electoral College; the UK has flexible elections and party selection.', 14),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'How do the UK and US differ in campaign finance?', 'US spending is much higher with fewer limits; the UK has strict spending limits and bans paid political TV ads.', 15),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the cultural explanation for gun control differences?', 'The US has a strong gun culture linked to history and the Second Amendment.', 16),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'Why is the US Supreme Court more powerful than the UK''s?', 'The codified, entrenched constitution gives the US Court power to overturn laws.', 17),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the rational explanation for Senate filibusters?', 'Senators use filibusters strategically to block legislation they oppose.', 18),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the significance of structural differences in executive power?', 'The US President has constitutional independence; the UK PM''s power depends on parliamentary majority.', 19),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What are the similarities between the UK and US?', 'Both are liberal democracies with two-party dominance, FPTP elections and independent judiciaries.', 20),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'What is the convergence thesis?', 'The idea that UK and US politics are becoming more similar, e.g. presidentialisation of UK PMs.', 21),
  ('Politics', 'Edexcel', 'alevel', '3A.6', 'Comparative Approaches', 'Why might convergence be limited?', 'Fundamental constitutional and institutional differences remain.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the state?', 'A political entity with sovereignty over a defined territory and population.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is national sovereignty?', 'A state''s supreme authority within its territory and independence from external control.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is a nation-state?', 'A state whose population shares a common national identity.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is globalisation?', 'The growing interconnectedness of states through economic, political and cultural flows.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is economic globalisation?', 'The integration of national economies through trade, investment and financial flows.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is political globalisation?', 'The growth of international organisations and cooperation beyond the state.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is cultural globalisation?', 'The spread of cultural ideas, products and values across borders.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the hyperglobalist view?', 'Globalisation has made states less relevant, creating a borderless world.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the sceptical view?', 'States remain powerful and globalisation is exaggerated.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the transformationalist view?', 'Globalisation is transforming states and power, but states remain important.', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the impact of globalisation on sovereignty?', 'States have less control over their economies, borders and policies.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the role of MNCs in globalisation?', 'They drive global trade and investment and can influence states.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the Washington Consensus?', 'Free-market policies promoted by the IMF, World Bank and US Treasury.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is humanitarian intervention?', 'Military intervention in another state to protect human rights.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the impact of globalisation on inequality?', 'It has lifted many out of poverty but increased inequality within some states.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is anti-globalisation?', 'Movements opposing globalisation''s economic, cultural and environmental impacts.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the impact of globalisation on the environment?', 'Increased emissions and resource use, but also international cooperation on environmental issues.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the impact of globalisation on culture?', 'Cultural homogenisation, but also hybridisation and local resistance.', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the digital revolution''s impact on globalisation?', 'Faster communication and information flows, e-commerce and social media across borders.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the role of global civil society?', 'NGOs and social movements that act across borders to influence global issues.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is the impact of globalisation on democracy?', 'It can spread democratic ideas but may reduce national democratic control.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.1', 'The State and Globalisation', 'What is deglobalisation?', 'A reduction in global integration, e.g. more protectionism after 2008 and COVID-19.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the United Nations?', 'An international organisation founded in 1945 to maintain peace and security and promote cooperation.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the UN Security Council?', 'The UN body responsible for international peace and security, with 5 permanent members and 10 elected members.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'Who are the P5?', 'The USA, the UK, France, Russia and China, each with a veto.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the UN General Assembly?', 'The UN''s main deliberative body, where all 193 members have one vote.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the International Monetary Fund?', 'An organisation promoting financial stability and providing loans to countries in crisis.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the World Bank?', 'An organisation providing loans and grants for development projects.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the World Trade Organization?', 'An organisation promoting free trade and settling trade disputes.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the G7?', 'A group of seven major advanced economies: USA, UK, France, Germany, Italy, Canada and Japan.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the G20?', 'A group of 19 major economies plus the EU (and the African Union since 2023), discussing global economic issues.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is NATO?', 'The North Atlantic Treaty Organization, a military alliance founded in 1949 for collective defence.', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is conditionality?', 'Conditions attached to IMF and World Bank loans, e.g. economic reforms.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What are structural adjustment programmes?', 'IMF and World Bank programmes requiring market reforms in exchange for loans.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the North–South divide?', 'The economic gap between wealthy developed countries and poorer developing countries.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the Millennium Development Goals?', 'Eight UN goals set in 2000 to reduce poverty and improve development by 2015.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the Sustainable Development Goals?', '17 UN goals set in 2015 to achieve sustainable development by 2030.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What are the criticisms of the UN Security Council?', 'The veto causes deadlock, and membership reflects 1945 power rather than today''s.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the role of NATO in global security?', 'Collective defence, crisis management and cooperative security.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is NATO expansion?', 'The growth of NATO membership, including Finland (2023) and Sweden (2024).', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the role of the WTO in trade disputes?', 'Its dispute settlement mechanism resolves trade conflicts between members.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is the Doha Round?', 'WTO trade negotiations started in 2001 that failed to reach agreement.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is economic governance?', 'The international institutions and rules governing the global economy.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.2', 'Global Governance: Political and Economic', 'What is political governance?', 'The international institutions and rules governing peace and security.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Universal Declaration of Human Rights?', 'A 1948 UN declaration setting out fundamental human rights.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the International Court of Justice?', 'The UN''s principal judicial body, settling disputes between states.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the International Criminal Court?', 'A court that prosecutes individuals for genocide, war crimes and crimes against humanity.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the European Court of Human Rights?', 'A court enforcing the European Convention on Human Rights.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Responsibility to Protect?', 'A 2005 UN principle that states must protect their populations, and the international community should intervene if they fail.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is humanitarian intervention?', 'Military intervention to prevent human rights abuses.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'Give an example of successful humanitarian intervention.', 'Sierra Leone (2000), where UK intervention helped end the civil war.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'Give an example of unsuccessful humanitarian intervention.', 'Libya (2011), which removed Gaddafi but led to instability and civil war.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Rwandan genocide (1994)?', 'The mass killing of Tutsis, which the international community failed to prevent.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What are the limits of the ICC?', 'Major powers, including the US, China and Russia, are not members; it relies on state cooperation.', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is global environmental governance?', 'International institutions and agreements addressing environmental issues.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Kyoto Protocol (1997)?', 'An agreement setting binding emissions targets for developed countries.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Paris Agreement (2015)?', 'An agreement to limit global warming to well below 2°C, with nationally determined contributions.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is COP?', 'Conference of the Parties, the annual UN climate change conference.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the Intergovernmental Panel on Climate Change?', 'The UN body assessing scientific evidence on climate change.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the tragedy of the commons in global politics?', 'Shared resources are overused because no single state has an incentive to limit its use.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the North–South divide on climate change?', 'Developing countries argue developed countries caused the problem and should bear more of the cost.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What are the limits of global environmental governance?', 'Lack of enforcement, national interests and free-riding.', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is common but differentiated responsibility?', 'All states share responsibility for climate change, but developed states have greater responsibility.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the role of NGOs in human rights?', 'They monitor abuses, campaign, and provide evidence, e.g. Amnesty International and Human Rights Watch.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is state sovereignty''s conflict with human rights?', 'Intervention to protect rights may violate a state''s sovereignty.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.3', 'Global Governance: Human Rights and Environmental', 'What is the significance of the Glasgow COP26 (2021)?', 'It agreed to "phase down" coal and strengthen emissions targets.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is hard power?', 'The use of military and economic force to influence others.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is soft power?', 'The ability to influence others through attraction, culture and values.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is smart power?', 'The combination of hard and soft power.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is a superpower?', 'A state with global influence across economic, military and cultural areas.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is a great power?', 'A state with significant influence, but less than a superpower.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is an emerging power?', 'A state whose power is growing, e.g. India and Brazil.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is unipolarity?', 'A world dominated by one superpower, e.g. the USA after the Cold War.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is bipolarity?', 'A world dominated by two superpowers, e.g. the USA and USSR during the Cold War.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is multipolarity?', 'A world with several centres of power.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the rise of China?', 'China''s growing economic, military and diplomatic power.', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the Belt and Road Initiative?', 'China''s global infrastructure investment programme to increase its influence.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the role of Russia in global politics?', 'A nuclear power and P5 member, asserting influence through military action, e.g. the invasion of Ukraine.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is a failed state?', 'A state unable to provide basic services or maintain control of its territory.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is a rogue state?', 'A state seen as a threat to world peace, e.g. North Korea.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is democratisation?', 'The spread of democracy to more states.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the democratic peace theory?', 'Democracies rarely go to war with each other.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is authoritarianism?', 'A system of government with concentrated power and limited political freedom.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is a semi-democratic state?', 'A state with some democratic features but significant restrictions on freedoms.', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is development and its measurement?', 'Improvement in living standards, measured by GDP per capita, HDI and other indicators.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the significance of BRICS?', 'A group of emerging economies (Brazil, Russia, India, China, South Africa and new members) challenging Western dominance.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is the Thucydides Trap?', 'The idea that war is likely when a rising power challenges an established power, e.g. the US and China.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.4', 'Power and Developments', 'What is polarity''s effect on global stability?', 'Realists argue bipolarity is most stable; others argue unipolarity or multipolarity can be stable.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is regionalism?', 'Cooperation and integration between states in a geographic region.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is economic regionalism?', 'Regional economic cooperation, e.g. free trade areas.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is security regionalism?', 'Regional cooperation on security issues.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is political regionalism?', 'Regional political cooperation and integration.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the European Union?', 'A political and economic union of 27 European states.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the European Commission?', 'The EU''s executive body, proposing legislation and enforcing EU law.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the European Parliament?', 'The EU''s directly elected legislative body.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the Council of the European Union?', 'The body representing member state governments, sharing legislative power with the Parliament.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the European Council?', 'The body of heads of state or government that sets the EU''s overall direction.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the Court of Justice of the EU?', 'The court interpreting EU law and ensuring its uniform application.', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the single market?', 'Free movement of goods, services, capital and people within the EU.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the eurozone?', 'EU member states that use the euro as their currency.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What was the Maastricht Treaty (1992)?', 'It created the EU, European citizenship and the path to the euro.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What was the Lisbon Treaty (2007)?', 'It reformed EU institutions and created Article 50 for leaving the EU.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is widening?', 'Increasing the number of EU member states.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is deepening?', 'Increasing integration between existing member states.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is supranationalism?', 'Decision-making above the level of the state, with binding authority.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is intergovernmentalism?', 'Cooperation between states where each retains sovereignty.', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is ASEAN?', 'The Association of Southeast Asian Nations, promoting regional cooperation.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the African Union?', 'An organisation promoting unity and cooperation among African states.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the eurozone crisis?', 'The debt crisis from 2009 affecting countries such as Greece, revealing flaws in monetary union without fiscal union.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.5', 'Regionalism and the EU', 'What is the impact of Brexit on the EU?', 'Loss of a major member, but the EU remained united in negotiations.', 22),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is realism?', 'A theory that states are the main actors in an anarchic international system, pursuing power and security.', 1),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is liberalism in global politics?', 'A theory that cooperation between states is possible through institutions, trade and democracy.', 2),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is anarchy in international relations?', 'The absence of a central authority above states.', 3),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the security dilemma?', 'When one state increases its security, others feel threatened and respond, leading to insecurity.', 4),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the balance of power?', 'States form alliances to prevent any one state from becoming too powerful.', 5),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is complex interdependence?', 'The liberal idea that states are linked by many connections, making conflict costly.', 6),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is global governance?', 'Cooperation between states and international organisations to manage global issues.', 7),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is constructivism?', 'A theory that international relations are shaped by ideas, identities and norms.', 8),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is neorealism?', 'A version of realism emphasising the structure of the international system rather than human nature.', 9),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is classical realism?', 'A version of realism emphasising human nature as the cause of state behaviour (Morgenthau).', 10),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is neoliberal institutionalism?', 'A liberal theory arguing institutions help states cooperate by reducing uncertainty.', 11),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the realist view of human nature?', 'Humans are selfish and power-seeking.', 12),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the liberal view of human nature?', 'Humans are capable of cooperation and progress.', 13),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the realist view of the state?', 'States are the main actors and pursue national interests.', 14),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the liberal view of international organisations?', 'They promote cooperation, peace and shared norms.', 15),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the realist view of international organisations?', 'They reflect the interests of powerful states and have limited independent influence.', 16),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the liberal view of war?', 'War can be prevented through democracy, trade and institutions.', 17),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the realist view of war?', 'War is inevitable in an anarchic system.', 18),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the significance of the 2022 Russian invasion of Ukraine for realism?', 'It supports realist views of power politics and the limits of international institutions.', 19),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the significance of the EU for liberalism?', 'It shows that cooperation and integration can bring peace between former enemies.', 20),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the English School?', 'A theory that states form an international society with shared rules and norms.', 21),
  ('Politics', 'Edexcel', 'alevel', '3B.6', 'Comparative Theories', 'What is the relevance of realism and liberalism today?', 'Both explain aspects of global politics: realism explains conflict and power; liberalism explains cooperation.', 22)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Politics' AND exam_board = 'Edexcel' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
